fragment FacetsFragment on Facet {
  name
  layout
  field
  maxValue
  filters {
    name
    value
    count
    isSelected
    url
    children {
      name
      value
      count
      isSelected
      url
      __typename
    }
    __typename
  }
  messages {
    type
    message
    url
    __typename
  }
  __typename
}

query categoryPLP($categoryId: String!, $first: Int!, $after: String, $catalog: String!, $filter: JSON, $sort: String) {
  category(
    catalog: $catalog
    first: $first
    categoryId: $categoryId
    filter: $filter
    after: $after
    sort: $sort
  ) {
    requestId
    category {
      name
      id
      url
      title
      heading
      description
      hierarchy {
        id
        name
        url
        __typename
      }
      __typename
    }
    totalCount
    edges {
      node {
        ...ProductsFragment
        __typename
      }
      __typename
    }
    facets {
      ...FacetsFragment
      __typename
    }
    sort {
      name
      value
      isSelected
      __typename
    }
    selectedFilters {
      name
      value
      field
      __typename
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      pages {
        value
        cursor
        __typename
      }
      firstPage {
        value
        cursor
        hasGap
        __typename
      }
      lastPage {
        value
        cursor
        hasGap
        __typename
      }
      __typename
    }
    __typename
  }
}"}

